(function(root){let pending=null;const targets={image:['Nén / đổi kích thước','#at-image-file'],crop:['Cắt / xoay ảnh','#it-crop-file'],batchimage:['Chuyển ảnh hàng loạt','#it-batch-files'],favicon:['Tạo favicon','#it-fav-file']};root.ToolHubMedia={attach(p,id,getBlob){const bar=document.createElement('div');bar.className='a-toolbar';const label=document.createElement('span');label.textContent='Chuyển kết quả sang:';bar.append(label);for(const[target,[name]]of Object.entries(targets)){if(target===id)continue;const btn=document.createElement('button');btn.textContent=name;btn.onclick=async()=>{const blob=await getBlob();if(!blob){p.querySelector('.a-status').textContent='Hãy tạo ảnh kết quả trước khi chuyển.';return}const ext=blob.type==='image/jpeg'?'jpg':blob.type==='image/webp'?'webp':'png';pending={target,file:new File([blob],'toolhub-transfer.'+ext,{type:blob.type})};const select=document.querySelector('#toolSelect');select.value=target;select.dispatchEvent(new Event('change',{bubbles:true}))};bar.append(btn)}p.append(bar)},consume(id,p){if(pending?.target!==id)return;const item=pending;pending=null;const input=p.querySelector(targets[id][1]);const transfer=new DataTransfer();transfer.items.add(item.file);input.files=transfer.files;input.dispatchEvent(new Event('change',{bubbles:true}))}}})(globalThis);
